pub fn is_sorted(arr: &Vec<i32>) -> bool {
    let n = arr.len();
    // Precondition says n > 0, but this also correctly handles n == 0 if ever called that way.
    if n <= 1 {
        return true;
    }

    for i in 0..(n - 1) {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}